const GMM = makeGMM();
const NTRAIN = 4096, DATA_SEED = 1234;
/** 固定的训练集（与随机种子无关：离线模型和页面里的实时训练用的是同一批 4096 个点） */
const trainSet = () => { const r = sampleGMM(NTRAIN, LM.rng(DATA_SEED)); return { X: r.X, lab: r.lab, n: NTRAIN }; };
/** 第 09 步的数字数据：5000 张训练（自编码器 + 潜空间扩散）+ 500 张测试，与 LM.digits 同一个生成器 */
const digitSets = () => { const r = LM.rng(2024); return { train: LM.digits.makeSet(5000, r), test: LM.digits.makeSet(500, r) }; };
